import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.DPTp4bo7.js";const u=JSON.parse('{"title":"Single-Forge Heavy Xiranite Using Clock Signals","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/single-forge-heavy-xiranite-using-clock-signals"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/single-forge-heavy-xiranite-using-clock-signals"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/single-forge-heavy-xiranite-using-clock-signals"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/single-forge-heavy-xiranite-using-clock-signals"}]]},"headers":[],"relativePath":"single-forge-heavy-xiranite-using-clock-signals.md","filePath":"logistics/src/page-zfM2Zf9DLRvNytZWjXcqpG.md"}'),s={name:"single-forge-heavy-xiranite-using-clock-signals.md"};function r(o,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><span class="logistics-source-anchor" id="基于时钟信号的单烘炉重息壤方案" aria-hidden="true"></span><h1 id="single-forge-heavy-xiranite-using-clock-signals" tabindex="-1">Single-Forge Heavy Xiranite Using Clock Signals <a class="header-anchor" href="#single-forge-heavy-xiranite-using-clock-signals" aria-label="Permalink to &quot;Single-Forge Heavy Xiranite Using Clock Signals&quot;">​</a></h1><blockquote><p>Source page ID: <code>zfM2Zf9DLRvNytZWjXcqpG</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=zfM2Zf9DLRvNytZWjXcqpG" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>When people return to Wuling in five years carrying Talos HC batteries, perhaps they will unearth this lost technology...</p><p>—kokobird</p><p><span id="source-block-pBzY7dd7zsMx3SZ4zmryDu"></span></p><span class="logistics-source-anchor" id="演示视频" aria-hidden="true"></span><h3 id="demonstration-video" tabindex="-1">Demonstration Video <a class="header-anchor" href="#demonstration-video" aria-label="Permalink to &quot;Demonstration Video&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV1yfdQBFEu7" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yfdQBFEu7</a></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7ee3b54fedb531c4.q90-8eb436dcc134b270.webp" alt="Single-Forge Heavy Xiranite Using Clock Signals"></p><p><span id="source-block-V1P5EQSkeyQ0eOWEfGABK8"></span></p><span class="logistics-source-anchor" id="基本原理解说" aria-hidden="true"></span><h3 id="basic-principles" tabindex="-1">Basic Principles <a class="header-anchor" href="#basic-principles" aria-label="Permalink to &quot;Basic Principles&quot;">​</a></h3><ol><li>Two Separating/Filling Unit pairs and one Seed-Picking Unit use belts to set matching periods, then start simultaneously for stable synchronized clock signals. Of every 14 Xiranite produced, 10 go toward making 1 Xiranite and 4 become 5 Xircon Effluent.</li><li>A 17-tile belt plus two machines gives a 38-second period. The video&#39;s 18-tile, 40-second period is more robust; I later found 17 tiles works too.</li><li>Jincao Seed controls the Stabilized Carbon signal. Separating/Filling Units control water for Xiranite and Xircon Effluent for Heavy Xiranite.</li><li>Adjust belt and pipe lengths to set signal delays and align production timing.</li></ol><p><span id="source-block-suuwxMTCaWf8PcR0zNEuJd"></span></p><span class="logistics-source-anchor" id="难点" aria-hidden="true"></span><h3 id="difficulties" tabindex="-1">Difficulties <a class="header-anchor" href="#difficulties" aria-label="Permalink to &quot;Difficulties&quot;">​</a></h3><ol><li>The splitter&#39;s round-robin order at the Forge entrance is hard to control. Before Heavy Xiranite production, 10 Xiranite must queue in 2x5 and enter in two steps. If the splitter sends its next Xiranite sideways rather than forward, the extra 2-second wait breaks the system. This is why 40 seconds originally offered some tolerance.</li><li>The 5 Xircon Effluent must enter rapidly, but Separating/Filling Units produce only one every 2 seconds. A pipe flow regularizer uses unequal lengths to make the 5 effluent units arrive nearly simultaneously. Building it is troublesome: changing pipe lengths and adding Pipe Bridges changed splitting order too.</li><li>Splitting the 14 output Xiranite with a seven-way splitter creates the same regularization problem. Here, prioritize 4 into the crucible and overflow the remainder instead.</li><li>Timing alignment: two Xiranite inputs supply 10 units, all of which must enter the Forge as quickly as possible. Water must enter later so Carbon holds Xiranite outside to queue. Queuing cannot last too long, or it blocks subsequent Carbon and leaves fewer than 10 Xiranite spaces next cycle.</li><li>Generally, the longer the Forge may idle, the fewer difficulties remain. Allowing 10 seconds of idle time might eliminate all four above.</li></ol><p><span id="source-block-lvXmi04Y6wZK6AqRrXzNAg"></span></p><span class="logistics-source-anchor" id="踩过的坑" aria-hidden="true"></span><h3 id="failed-attempts" tabindex="-1">Failed Attempts <a class="header-anchor" href="#failed-attempts" aria-label="Permalink to &quot;Failed Attempts&quot;">​</a></h3><ol><li>Copy signals with Item Control Ports to synchronize clocks—breaks offline.</li><li>Separate two bottle types in one Separating Unit for a sequence of 10 water and 5 Xircon Effluent, sorting through control ports—breaks offline.</li><li>Regularize the five-of-seven Xiranite using the tape method—breaks offline.</li><li>Regularize Xircon Effluent with the pipe tape method—I cannot work out the mixed-pipe clock timing.</li></ol><p><span id="source-block-vxE22YOQkvP9lAUpY243Iy"></span></p><span class="logistics-source-anchor" id="未解之谜" aria-hidden="true"></span><h3 id="unsolved-mysteries" tabindex="-1">Unsolved Mysteries <a class="header-anchor" href="#unsolved-mysteries" aria-label="Permalink to &quot;Unsolved Mysteries&quot;">​</a></h3><ol><li>Although the belt period is 38 seconds, stable operation measures a very strict 38.5-second period... I cannot find where the 0.5 comes from.</li><li>It broke after the 1.3 update, yet surprisingly did not break after 1.4.</li></ol><p>Translation note: The source&#39;s “10 Xiranite make 1 Xiranite” is retained despite its apparent missing Heavy qualifier. “Talos HC batteries” is a speculative future-item reference, not a verified current item. Image text is retained.</p></div>',1)])])}const g=i(s,[["render",r]]);export{u as __pageData,g as default};
